/**
 * Lexington v2.0 - Premium Ghost Theme JavaScript
 * Author: Wasim Akram Developer | prodigitalwasim@gmail.com
 * Features: Dark mode, sticky header, mobile nav, search, TOC, reading progress, lazy loading, copy link
 */
(function(){
"use strict";

/* ── DOM Ready ────────────────────────────────────────────────────── */
document.addEventListener("DOMContentLoaded", function() {

/* ── 1. Dark Mode Toggle ───────────────────────────────────────────── */
const themeToggle = document.getElementById("theme-toggle");
const html = document.documentElement;
const sunIcon = document.querySelector(".theme-toggle-icon--sun");
const moonIcon = document.querySelector(".theme-toggle-icon--moon");

function getTheme() {
    return localStorage.getItem("lexington-theme") || "";
}
function setTheme(theme) {
    if (theme === "dark") {
        html.classList.add("dark");
        html.setAttribute("data-theme-manual", "");
        if (sunIcon) sunIcon.style.display = "block";
        if (moonIcon) moonIcon.style.display = "none";
    } else {
        html.classList.remove("dark");
        html.removeAttribute("data-theme-manual");
        if (sunIcon) sunIcon.style.display = "none";
        if (moonIcon) moonIcon.style.display = "block";
    }
    localStorage.setItem("lexington-theme", theme);
}

const saved = getTheme();
if (saved === "dark") setTheme("dark");
else if (saved === "light") setTheme("light");

if (themeToggle) {
    themeToggle.addEventListener("click", function() {
        const isDark = html.classList.contains("dark");
        setTheme(isDark ? "light" : "dark");
    });
}

/* ── 2. Sticky Header with Scroll Detection ────────────────────────── */
const header = document.getElementById("site-header");
if (header) {
    let lastScroll = 0;
    window.addEventListener("scroll", function() {
        const currentScroll = window.scrollY;
        if (currentScroll > 10) header.classList.add("scrolled");
        else header.classList.remove("scrolled");
        lastScroll = currentScroll;
    }, { passive: true });
}

/* ── 3. Mobile Navigation ──────────────────────────────────────────── */
const mobileToggle = document.getElementById("mobile-menu-toggle");
const mobileNav = document.getElementById("mobile-nav");
const mobileOverlay = document.getElementById("mobile-nav-overlay");
const mobileClose = document.getElementById("mobile-nav-close");

function openMobileNav() {
    if (mobileNav) mobileNav.classList.add("active");
    if (mobileOverlay) mobileOverlay.classList.add("active");
    if (mobileToggle) { mobileToggle.classList.add("active"); mobileToggle.setAttribute("aria-expanded", "true"); }
    document.body.style.overflow = "hidden";
}
function closeMobileNav() {
    if (mobileNav) mobileNav.classList.remove("active");
    if (mobileOverlay) mobileOverlay.classList.remove("active");
    if (mobileToggle) { mobileToggle.classList.remove("active"); mobileToggle.setAttribute("aria-expanded", "false"); }
    document.body.style.overflow = "";
}
if (mobileToggle) mobileToggle.addEventListener("click", openMobileNav);
if (mobileClose) mobileClose.addEventListener("click", closeMobileNav);
if (mobileOverlay) mobileOverlay.addEventListener("click", closeMobileNav);
document.addEventListener("keydown", function(e) { if (e.key === "Escape") closeMobileNav(); });

/* ── 4. Search Modal with Ghost API ────────────────────────────────── */
const searchToggle = document.getElementById("search-toggle");
const searchOverlay = document.querySelector(".search-modal-overlay");
const searchModal = document.querySelector(".search-modal");
const searchCloseBtn = document.querySelector(".search-modal-close");
const searchInput = document.querySelector(".search-modal-input");
const searchResults = document.querySelector(".search-modal-results");
let searchTimeout = null;

function openSearch() {
    if (searchOverlay) searchOverlay.classList.add("active");
    if (searchModal) searchModal.classList.add("active");
    document.body.style.overflow = "hidden";
    setTimeout(function() { if (searchInput) searchInput.focus(); }, 100);
}
function closeSearch() {
    if (searchOverlay) searchOverlay.classList.remove("active");
    if (searchModal) searchModal.classList.remove("active");
    document.body.style.overflow = "";
    if (searchInput) searchInput.value = "";
    if (searchResults) searchResults.innerHTML = "";
}
if (searchToggle) searchToggle.addEventListener("click", openSearch);
if (searchCloseBtn) searchCloseBtn.addEventListener("click", closeSearch);
if (searchOverlay) searchOverlay.addEventListener("click", closeSearch);
document.addEventListener("keydown", function(e) {
    if (e.key === "Escape") closeSearch();
    if ((e.metaKey || e.ctrlKey) && e.key === "k") { e.preventDefault(); openSearch(); }
});

if (searchInput && searchResults) {
    searchInput.addEventListener("input", function() {
        clearTimeout(searchTimeout);
        const q = searchInput.value.trim();
        if (!q) { searchResults.innerHTML = ""; return; }
        searchResults.innerHTML = '<div class="search-modal-loading">Searching...</div>';
        searchTimeout = setTimeout(function() {
            fetch("/ghost/api/v4/content/posts/?key=" + ghostSearchKey + "&fields=title,slug,excerpt,feature_image&limit=5&filter=title%3A~" + encodeURIComponent(q) + "%2Bexcerpt%3A~" + encodeURIComponent(q))
            .then(function(r) { return r.json(); })
            .then(function(data) {
                if (data.posts && data.posts.length) {
                    searchResults.innerHTML = data.posts.map(function(post) {
                        return '<a href="/' + post.slug + '/" class="search-result-item">' +
                            '<div class="search-result-title">' + (post.title || "") + '</div>' +
                            (post.excerpt ? '<div class="search-result-excerpt">' + post.excerpt + '</div>' : '') +
                        '</a>';
                    }).join("");
                } else {
                    searchResults.innerHTML = '<div class="search-modal-empty">No results found for "' + q.replace(/</g, "&lt;") + '"</div>';
                }
            })
            .catch(function() {
                searchResults.innerHTML = '<div class="search-modal-empty">Search failed. Please try again.</div>';
            });
        }, 300);
    });
}

/* Hero search form redirect to search modal */
const heroSearchForm = document.querySelector("[data-search-form]");
if (heroSearchForm) {
    heroSearchForm.addEventListener("submit", function(e) {
        e.preventDefault();
        openSearch();
        const heroInput = heroSearchForm.querySelector("[data-search-input]");
        if (heroInput && searchInput) {
            searchInput.value = heroInput.value;
            searchInput.dispatchEvent(new Event("input"));
        }
    });
}

/* ── 5. Table of Contents (Auto-Generated) ────────────────────────── */
const postBody = document.querySelector(".post-body");
const tocList = document.querySelector(".toc-list");
if (postBody && tocList) {
    const headings = postBody.querySelectorAll("h2, h3");
    if (headings.length >= 3) {
        headings.forEach(function(heading, index) {
            if (!heading.id) heading.id = "section-" + (index + 1);
            const link = document.createElement("a");
            link.href = "#" + heading.id;
            link.className = "toc-link";
            link.textContent = heading.textContent;
            link.setAttribute("data-level", heading.tagName.toLowerCase());
            link.addEventListener("click", function(e) {
                e.preventDefault();
                heading.scrollIntoView({ behavior: "smooth", block: "start" });
            });
            tocList.appendChild(link);
        });
        /* Active TOC tracking */
        const tocLinks = tocList.querySelectorAll(".toc-link");
        window.addEventListener("scroll", function() {
            let current = "";
            headings.forEach(function(h) {
                const rect = h.getBoundingClientRect();
                if (rect.top <= 120) current = h.id;
            });
            tocLinks.forEach(function(link) {
                link.classList.toggle("active", link.getAttribute("href") === "#" + current);
            });
        }, { passive: true });
    } else {
        const toc = document.querySelector(".toc");
        if (toc) toc.style.display = "none";
    }
}

/* ── 6. Reading Progress Bar ───────────────────────────────────────── */
const progressBar = document.getElementById("reading-progress");
if (progressBar && postBody) {
    window.addEventListener("scroll", function() {
        const rect = postBody.getBoundingClientRect();
        const total = rect.height - window.innerHeight;
        const progress = total > 0 ? Math.min(Math.max((window.scrollY - rect.top + window.innerHeight) / (rect.height + window.scrollY) * 100, 0), 100) : 0;
        progressBar.style.width = progress + "%";
        progressBar.setAttribute("aria-valuenow", Math.round(progress));
    }, { passive: true });
}

/* ── 7. Lazy Load Images ───────────────────────────────────────────── */
if ("IntersectionObserver" in window) {
    const lazyImages = document.querySelectorAll("img[data-src]");
    const imageObserver = new IntersectionObserver(function(entries) {
        entries.forEach(function(entry) {
            if (entry.isIntersecting) {
                const img = entry.target;
                img.src = img.dataset.src;
                if (img.dataset.srcset) img.srcset = img.dataset.srcset;
                img.removeAttribute("data-src");
                img.removeAttribute("data-srcset");
                imageObserver.unobserve(img);
            }
        });
    }, { rootMargin: "200px 0px" });
    lazyImages.forEach(function(img) { imageObserver.observe(img); });
}

/* ── 8. Copy Link on Heading Click ─────────────────────────────────── */
if (postBody) {
    postBody.querySelectorAll("h2, h3").forEach(function(heading) {
        heading.style.cursor = "pointer";
        heading.addEventListener("click", function() {
            const url = window.location.origin + window.location.pathname + "#" + heading.id;
            if (navigator.clipboard) {
                navigator.clipboard.writeText(url).then(function() {
                    const original = heading.style.color;
                    heading.style.color = "var(--accent)";
                    setTimeout(function() { heading.style.color = original; }, 1000);
                });
            } else {
                window.location.hash = heading.id;
            }
        });
    });
}

/* ── 9. Smooth Scroll for Anchor Links ─────────────────────────────── */
document.querySelectorAll('a[href^="#"]').forEach(function(anchor) {
    anchor.addEventListener("click", function(e) {
        const target = document.querySelector(this.getAttribute("href"));
        if (target) {
            e.preventDefault();
            target.scrollIntoView({ behavior: "smooth", block: "start" });
        }
    });
});

}); /* end DOMContentLoaded */
})();